type Rule = [RegExp, (m: RegExpMatchArray, t: (s: string) => string) => string];

/** Texts built with numbers or names inside. Tried in order when there is no exact entry above. */
export const DE_PATTERNS: Rule[] = [
  [/^(\d+) of (\d+) profiles$/, (m) => `${m[1]} von ${m[2]} Profilen`],
  [/^(\d+) agreed to offers$/, (m) => `${m[1]} mit Einwilligung für Angebote`],
  [/^(\d+) strong fits$/, (m) => `${m[1]} passen sehr gut`],
  [/^(\d+) this week$/, (m) => `${m[1]} diese Woche`],
  [/^New replies \((\d+)\)$/, (m) => `Neue Antworten (${m[1]})`],
  [/^Tasks \((\d+) open\)$/, (m) => `Aufgaben (${m[1]} offen)`],
  [/^Covers a customer may be missing, found by the rules\. (\d+) won this year\.$/, (m) => `Absicherungen, die einem Kunden fehlen könnten, gefunden durch die Regeln. ${m[1]} heuer gewonnen.`],
  [/^Message to (.+)$/, (m) => `Nachricht an ${m[1]}`],
  [/^Contact by (.+)$/, (m, t) => `Kontakt per ${t(m[1])}`],
  [/^Week of (.+): (\d+) messages$/, (m) => `Woche ab ${m[1]}: ${m[2]} Nachrichten`],
  [/^Delete campaign (.+)$/, (m) => `Kampagne ${m[1]} löschen`],
  [/^End date of (.+) policy$/, (m, t) => `Enddatum des Vertrags ${t(m[1])}`],
  [/^Remove (.+) policy$/, (m, t) => `Vertrag ${t(m[1])} entfernen`],
  [/^Status of (.+) opportunity$/, (m, t) => `Status der Chance ${t(m[1])}`],
  [/^Status for (.+), (.+)$/, (m, t) => `Status für ${m[1]}, ${t(m[2])}`],
  [/^Field for column (.*)$/, (m) => `Feld für Spalte ${m[1]}`],
  [/^Remove recommendation rule for (.+)$/, (m, t) => `Empfehlungsregel für ${t(m[1])} entfernen`],
  [/^Remove (rule|guide) (.+)$/, (m) => `${m[1] === "rule" ? "Regel" : "Wissen"} ${m[2]} entfernen`],
  [/^Remove (.+)$/, (m) => `${m[1]} entfernen`],
  [/^(.+): (agreed|not agreed)$/, (m, t) => `${t(m[1])}: ${t(m[2])}`],
  [/^This message contains "(.+)", which your own rules say to avoid\.$/, (m) => `Diese Nachricht enthält „${m[1]}“, das Sie laut Ihren eigenen Regeln vermeiden wollen.`],
  // reasons with the income note appended
  [/^(.+\.) Net income is (.+) a month; size the cover to that\.$/, (m, t) => `${t(m[1])} Nettoeinkommen: ${t(m[2].replace(/^under/, "Under").replace(/^over/, "Over"))} pro Monat; richten Sie die Absicherung daran aus.`],
  [/^Aged (\d+) with no private pension plan\. Starting early gives savings the longest time to grow\.$/, (m) => `${m[1]} Jahre alt, ohne private Pensionsvorsorge. Ein früher Start gibt dem Ersparten die längste Zeit zu wachsen.`],
  [/^Aged (\d+) with no private pension plan yet\.$/, (m) => `${m[1]} Jahre alt, noch ohne private Pensionsvorsorge.`],
  [/^Aged (\d+): few saving years are left, but a top-up may still help\.$/, (m) => `${m[1]} Jahre alt: Es bleiben wenige Ansparjahre, aber eine Aufstockung kann noch helfen.`],
  [/^Youngest child is (under one|\d+)\. A plan started now has the longest time to grow\.$/, (m) => `Das jüngste Kind ist ${m[1] === "under one" ? "unter einem Jahr" : m[1]}. Eine jetzt begonnene Vorsorge hat die längste Zeit zu wachsen.`],
  [/^Youngest child is (\d+)\. A plan can still grow for some years before they are adults\.$/, (m) => `Das jüngste Kind ist ${m[1]}. Eine Vorsorge kann bis zur Volljährigkeit noch einige Jahre wachsen.`],
  // held policies
  [/^(Policy (.+?)\.|Held with us\.)( Ended (.+): check whether it was renewed\.| Ends in (\d+) days: talk about renewal\.| Runs until (.+)\.)?$/, (m) => {
    const head = m[2] ? `Polizze ${m[2]}.` : "Bei uns abgeschlossen.";
    const tail = m[4] ? ` Am ${m[4]} abgelaufen: prüfen Sie, ob verlängert wurde.` : m[5] ? ` Läuft in ${m[5]} Tagen ab: sprechen Sie die Verlängerung an.` : m[6] ? ` Läuft bis ${m[6]}.` : "";
    return head + tail;
  }],
  [/^Agreed to offers, without (.+)$/, (m, t) => `Angeboten zugestimmt, ohne ${t(m[1])}`],
  [/^Agreed to offers, with (.+)$/, (m, t) => `Angeboten zugestimmt, mit ${t(m[1])}`],
];
